// GENERATED by the Captain.Food codegen from specs/configuration.yaml — do not edit by hand.
//
// The typed runtime configuration (PROP-20260729-004500, issue #246). Every setting the app
// needs is DECLARED in the spec and read here, once, at startup — never through a scattered
// `env::var` call. A missing REQUIRED key (per the resolved `APP_PROFILE`) is collected with
// every other missing key and reported together; the composition root then stops the app.
//
// Secrets are never rendered: the boot report shows `set` / `unset`, and for a key declaring
// `mode_of: stripe` the derived test/live mode — never the value.

use std::fmt;

/// Which keys are required. Declared via `APP_PROFILE`, never inferred from the host or from
/// a key's prefix — an inferred profile is wrong exactly when it matters most (a mode switch).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Profile {
    Development,
    Staging,
    Production,
}

impl Profile {
    pub fn as_str(self) -> &'static str {
        match self {
            Profile::Development => "development",
            Profile::Staging => "staging",
            Profile::Production => "production",
        }
    }
}

impl fmt::Display for Profile {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Lenient boolean parsing (ADR-20260728-224500): `true/1/yes/on` and `false/0/no/off`,
/// case-insensitive, trimmed, wrapping quotes stripped. An unrecognised value falls back to the
/// declared default AND says so — a typo must never be silently interpreted as either state.
fn parse_bool(name: &str, raw: &str, default: bool) -> bool {
    match raw.trim().trim_matches(['"', '\'']).trim().to_ascii_lowercase().as_str() {
        "true" | "1" | "yes" | "on" => true,
        "false" | "0" | "no" | "off" => false,
        "" => default,
        other => {
            println!(
                "{name}: unrecognised value {other:?} -- using the default ({default}). \
Accepted: true/1/yes/on, false/0/no/off."
            );
            default
        }
    }
}

/// Read a key, treating an empty/whitespace-only value as ABSENT — a dashboard field someone
/// cleared must count as missing, not as an empty string that satisfies a requirement.
fn raw(name: &str) -> Option<String> {
    std::env::var(name).ok().map(|v| v.trim().to_string()).filter(|v| !v.is_empty())
}

/// Validate a value against its scalar's regex. Compiled once per pattern and cached: startup
/// cost is a handful of small regexes, paid to make "present but unusable" impossible to miss.
fn matches_pattern(pattern: &str, value: &str) -> bool {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    static CACHE: OnceLock<Mutex<HashMap<String, regex::Regex>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    let mut guard = cache.lock().unwrap_or_else(|p| p.into_inner());
    let re = guard.entry(pattern.to_string()).or_insert_with(|| {
        regex::Regex::new(pattern).expect("configuration pattern compiles (checked by codegen)")
    });
    re.is_match(value)
}

/// The non-secret values DECLARED per profile (`deploy:` in configuration.yaml), baked into the
/// binary (PROP-20260729-014500 D5). Render has no per-deploy env override, so this is the only
/// way to make configuration part of the ARTIFACT: the digest then determines behaviour, and a
/// rollback restores the configuration that shipped with that build. Secrets are never here —
/// the GHCR package is public, so a baked value is world-readable.
fn baked(name: &str, profile: Profile) -> Option<&'static str> {
    BAKED
        .iter()
        .find(|(k, p, _)| *k == name && *p == profile.as_str())
        .map(|(_, _, v)| *v)
}

/// Stripe mode from the key prefix — reportable where the key itself never is.
fn stripe_mode(value: &str) -> &'static str {
    if value.starts_with("sk_live_") {
        "live"
    } else if value.starts_with("sk_test_") {
        "test"
    } else {
        "unknown"
    }
}

/// A required key that was not supplied, with the `gates` text from the spec.
#[derive(Debug, Clone)]
pub struct MissingKey {
    pub name: &'static str,
    pub gates: &'static str,
}

/// A key that WAS supplied but does not satisfy its scalar. Carries the expected shape, never
/// the offending value: a malformed secret is still a secret.
#[derive(Debug, Clone)]
pub struct InvalidKey {
    pub name: &'static str,
    pub scalar: &'static str,
    pub pattern: &'static str,
    pub gates: &'static str,
}

/// Everything wrong with the configuration, in one report — never just the first problem. An
/// operator who learns of one bad key per deploy cycle fixes a three-key outage in three deploys.
#[derive(Debug, Clone, Default)]
pub struct ConfigProblems {
    pub missing: Vec<MissingKey>,
    pub invalid: Vec<InvalidKey>,
}

impl ConfigProblems {
    pub fn is_empty(&self) -> bool {
        self.missing.is_empty() && self.invalid.is_empty()
    }

    pub fn len(&self) -> usize {
        self.missing.len() + self.invalid.len()
    }
}

/// The report the app prints before it stops (production/staging) or continues (development).
#[derive(Debug, Clone)]
pub struct MissingConfig {
    pub profile: Profile,
    pub problems: ConfigProblems,
}

impl fmt::Display for MissingConfig {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(
            f,
            "FATAL: {} configuration problem(s) (profile: {})\n",
            self.problems.len(),
            self.profile
        )?;
        let width = self
            .problems
            .missing
            .iter()
            .map(|m| m.name.len())
            .chain(self.problems.invalid.iter().map(|i| i.name.len()))
            .max()
            .unwrap_or(0);
        if !self.problems.missing.is_empty() {
            writeln!(f, "MISSING — required in this profile:")?;
            for m in &self.problems.missing {
                writeln!(f, "  {:width$}  {}", m.name, m.gates, width = width)?;
            }
            writeln!(f)?;
        }
        if !self.problems.invalid.is_empty() {
            writeln!(f, "INVALID — supplied but malformed (the value is never printed):")?;
            for i in &self.problems.invalid {
                writeln!(f, "  {:width$}  expected {} matching {}", i.name, i.scalar, i.pattern, width = width)?;
                writeln!(f, "  {:width$}  {}", "", i.gates, width = width)?;
            }
            writeln!(f)?;
        }
        write!(f, "Fix them in the service environment and redeploy. Nothing was started.")
    }
}

/// The resolved configuration. Built once, injected — never re-read from env.
#[derive(Debug, Clone)]
pub struct Config {
    pub profile: Profile,
    /// Postgres pool: the event store, every read model and every background worker. Unset, /health reports `not_configured` (503) and no worker is constructed at all.
    pub database_url: String,
    /// Supabase Auth base URL for the passwordless OTP/magic-link flows. Unset, the identity service is the fail-closed stand-in and every login is refused.
    pub supabase_url: String,
    /// Supabase anon key sent as the `apikey` header on OTP flows. Unset, identity is fail-closed (auth stays anonymous-only).
    pub supabase_publishable_key: String,
    /// JWKS endpoint used to verify Supabase-issued JWTs. Unset, tokens cannot be verified and every authenticated request falls back to anonymous.
    pub supabase_jwks_url: String,
    /// AES-256-GCM key (32 bytes, 64 hex chars or base64) encrypting parked auth sessions at rest. Unset OR malformed, the store is the no-op: parking succeeds, claiming yields nothing, and login SILENTLY degrades to anonymous-only. Rotating it invalidates every in-flight login.
    pub auth_session_key: String,
    /// Shared secret verifying Supabase's SMS send-hook callbacks. Unset, the hook endpoint fails closed.
    pub supabase_sms_hook_secret: Option<String>,
    /// Stripe API key for PaymentIntents. Unset, the payment gateway is the fail-closed stand-in and no checkout can complete. The `sk_test_` / `sk_live_` prefix determines the MODE, which is reported (never the key) so "is production actually live?" is answerable.
    pub stripe_secret_key: String,
    /// HMAC secret verifying `POST /adapters/stripe/webhooks` signatures. Unset, the endpoint fails closed (503) and PaymentCaptured NEVER REACHES THE DOMAIN — the customer is charged and the restaurant is never told. Stripe issues a DIFFERENT secret per mode: it must be switched together with STRIPE_SECRET_KEY.
    pub stripe_webhook_secret: String,
    /// Honeycomb INGEST key for the OTLP trace/metric exporter (`x-honeycomb-team`). Unset, the exporter is not constructed at all and the app runs with local structured logs only — every span is built and dropped, so a production incident is diagnosed by reading stdout, which is the pre-#191 situation. This must be an INGEST key: a management key (`<id>:<secret>`, what the Honeycomb MCP server and Query API use) has a different shape and is rejected at startup rather than failing as an opaque 401 on the first export.
    pub honeycomb_api_key: Option<String>,
    /// OTLP/HTTP base endpoint. Defaults to and is baked as the **EU** host (`api.eu1.honeycomb.io`) — the US host `api.honeycomb.io` is a GDPR decision, not a preference, because spans carry customer and order ids (ADR-0042 pinned data to Frankfurt). Pointed at the wrong region, exports 401 against an account that does not hold the key and telemetry is silently absent.
    pub honeycomb_api_endpoint: String,
    /// The Honeycomb service/dataset traces land in, also reported as the OTel `service.name` resource attribute. Baked per profile so staging traffic can never be read as production: sharing one dataset makes a staging load test look like a Friday-night peak and corrupts every SLO computed from it.
    pub honeycomb_dataset: String,
    /// Head-sampling probability, parent-respecting. Baked at `1.0` (keep everything) because PROP-170500 D2's reasoning holds at V0 volume: "head-sampling would mostly discard the interesting traces". This is the dial to turn DOWN if ingest cost becomes real — turning it down before there is volume buys nothing and loses the traces that explain the incidents. Set to 0 and traces stop; the metrics and logs continue, so the app looks healthy while being undiagnosable.
    pub otel_traces_sample_ratio: String,
    /// Minimum severity for the structured JSON log layer. At `error` the boot report and every worker lifecycle line disappear, which is how a paused pipeline becomes invisible (issue #220) — so the baked value stays `info` and `debug` is an incident tool, not a default.
    pub log_level: String,
    /// HubRise app client id for the OAuth connect flow. OPTIONAL in every profile and CURRENTLY UNSET — we do not have one yet (2026-07-29). Unset, restaurants cannot START a HubRise connection; already connected locations are unaffected, since the worker uses their per-connection tokens. When a client id is obtained it is NOT a secret (an OAuth client id is public by construction), so it gets literal per-profile `deploy` values here rather than a repo secret.
    pub hubrise_client_id: Option<String>,
    /// HMAC key verifying `X-HubRise-Hmac-SHA256` on HubRise callbacks. Unset, the endpoint fails closed.
    pub hubrise_webhook_secret: Option<String>,
    /// Comma-separated pre-shared tokens for EXTERNAL machine callers (`X-External-Api-Key`, ADR-0047). Unset, only a Supabase JWT with captain_role EXTERNAL reaches /external.
    pub external_api_tokens: Option<String>,
    /// Shared secret for `POST /internal/sirene/drain` and `/internal/inbound/drain` (`x-internal-token`). Unset, both fail closed (503) and the CI sweep cannot wake the worker — the drain then waits for its hourly poll instead of starting in seconds.
    pub internal_trigger_token: Option<String>,
    /// Hard ceiling, in seconds, on how long ONE delivery channel may sit on an offer before the timeout worker escalates to the next ranked channel. Set it too high and a channel that never answers holds an accepted order hostage past the ETA the customer was shown; set it too low and a partner that would have accepted gets pulled off the job. NOT a repo secret, deliberately, though it was asked for as one (2026-07-29). It is a NON-SECRET tuning number, and a non-secret in Actions secrets is unreadable configuration — you could not open this repo and learn what ceiling production applies, which is the whole failure this file exists to end (and `config-nonsecret-from-secret` rejects it). The `default` here IS the CI-supplied value: it is baked into the artifact, printed in the boot report, and overridable per profile by adding a `deploy:` block, or in seconds during an incident by setting the env var. Everything a repo secret would have given, minus the opacity.
    pub delivery_offer_max_ttl_seconds: i64,
    /// In-process projection worker (ADR-0040). OFF, no read model advances — queries serve stale data indefinitely. Readiness at GET /projector.
    pub run_projector: bool,
    /// In-process saga runner (actors.yaml process managers). OFF, no cross-aggregate reaction fires. Readiness at GET /saga.
    pub run_process_managers: bool,
    /// Inbound-events drain (ADR-20260720-015400) delivering adapter-staged facts through the write path, plus the command_journal stale sweep. OFF, every webhook-staged fact accumulates undelivered.
    pub run_inbound_drain: bool,
    /// Retention sweep over terminal journal/mirror rows. OFF, nothing expires and storage grows without bound.
    pub run_retention_sweep: bool,
    /// SIRENE staging drain (ADR-0045): translates `external_sirene_restaurants` rows through the ACL and releases their payloads. DEFAULT OFF since 2026-07-28 (paused with the CI sweep, issue #220). OFF, staged rows stay PENDING indefinitely and registry-driven prospect creation does not happen. Readiness at GET /sirene.
    pub run_sirene_worker: bool,
    /// Delivery-offer timeout loop. OFF, an offer nobody answers is never expired and the order waits on a rider who is not coming.
    pub run_delivery_offer_timeout: bool,
    /// OVH API application key — one of the THREE values the v1 signature needs (`X-Ovh-Application`). Missing any one of the three and the SMS client is None, so the Send-SMS hook 503s and Supabase surfaces an OTP delivery error to the customer.
    pub ovh_application_key: Option<String>,
    /// OVH API application secret — the HMAC key for `X-Ovh-Signature` (`sha1(secret + "+" + consumerKey + "+" + METHOD + "+" + URL + "+" + BODY + "+" + timestamp)`). The one value here that grants send capability; treat it as a payment credential.
    pub ovh_application_secret: Option<String>,
    /// OVH API consumer key — binds the application credentials to the authorised access rules (`POST /sms/*/jobs`). A key whose rules omit that path authenticates fine and then fails the send, which is why the rule set matters as much as the value.
    pub ovh_consumer_key: Option<String>,
    /// The OVH SMS account the messages are billed to (e.g. `sms-ab12345-1`), used as `POST /sms/{serviceName}/jobs`. BORDERLINE as a secret: it grants nothing on its own — the credential triplet does that — but it embeds the OVH account identifier. Declared `secret: true` because it is already held as a repo secret and its literal value is not in this repository; if you would rather it be readable, give it literal per-profile `deploy` values instead and drop `secret`. Also note the account must hold SMS CREDITS: with none, the credentials authenticate and the send still fails at OVH.
    pub ovh_sms_service_name: Option<String>,
    /// The sender name shown on the SMS. Unset, the client substitutes `CaptainFood`. Declares NO `default` deliberately: the fallback lives in `OvhSmsClient::from_env`, and a second copy here would be two sources of truth for one value. OVH requires a sender to be REGISTERED and approved before it can be used, so an unapproved name fails at send time, not at startup.
    pub ovh_sms_sender: Option<String>,
    /// OVH API base URL. Unset, the client substitutes `https://eu.api.ovh.com/1.0` — the EU region, which is the deliberate choice for data residency (ADR-20260722-174500) and must match the region the API credentials were created in. Declares NO `default` for the same reason as OVH_SMS_SENDER: the fallback is the client's.
    pub ovh_endpoint: Option<String>,
    /// Static bearer key for the Avelo37 partner API. Unset, the outbound gateway is not built and jobs reach independent riders only — no delivery is lost, but the partner channel is silently absent, so an operator expecting Avelo37 coverage sees none.
    pub avelo37_api_key: Option<String>,
    /// Base-URL override pointing the client at a staging or mock Avelo37. Unset, the client uses its own production constant -- hence no `default` here, which would duplicate it.
    pub avelo37_api_base_url: Option<String>,
    /// HMAC key verifying inbound Avelo37 delivery-status callbacks. Unset, the webhook route fails closed: `DeliveryStatusUpdated` facts stop arriving and a delivery's tracking freezes at its last known state while the courier is in fact moving.
    pub avelo37_webhook_secret: Option<String>,
    /// Uber Direct customer/organization id — the `{customer_id}` path segment on every API call. Grants nothing on its own, but it identifies our Uber account, so it is treated as a credential rather than published in the repo (the same call made for OVH_SMS_SERVICE_NAME). One of the four the adapter requires TOGETHER; missing any one of them is reported as a misconfiguration rather than downgraded to a silent no-op.
    pub uber_direct_customer_id: Option<String>,
    /// OAuth2 client-credentials client id — Uber's dashboard also calls this the application id. Public by construction, like any OAuth client id, but it is per-app and per-mode, so it travels with its secret rather than being baked as a literal. Required with the other three; unset, no Uber Direct channel and jobs fall through to the next ranked one.
    pub uber_direct_client_id: Option<String>,
    /// OAuth2 client-credentials client secret — the token manager cannot mint an access token without it, so every create-delivery call fails at authentication. This is the one value here that grants the ability to dispatch deliveries and be billed for them.
    pub uber_direct_client_secret: Option<String>,
    /// Raw-body HMAC-SHA256 key verifying `X-Uber-Signature` on inbound callbacks. Unset, the webhook fails closed and delivery progress stops updating mid-delivery — the customer watches a courier that has in fact already arrived. Issued separately from the OAuth credentials, on Uber's webhook configuration page, and it is per-app: a test app and a live app do not share it.
    pub uber_direct_webhook_secret: Option<String>,
    /// API base-URL override (tests point this at a local mock). Unset, the adapter's own production constant applies -- no `default` here for the same reason.
    pub uber_direct_base_url: Option<String>,
    /// OAuth2 token-endpoint override. Unset, the adapter's own constant applies.
    pub uber_direct_token_url: Option<String>,
    /// OAuth2 scope override. Unset, the adapter requests its default delivery scope; too narrow a scope here surfaces as an authorization failure on create-delivery, not at startup.
    pub uber_direct_scope: Option<String>,
    /// JSON array of self-hosted CoopCycle co-op instances (per-instance OAuth2 client + token URL) — a federation registry rather than one endpoint, which is why it is a JSON document and not a set of scalar keys. Unset or empty, the adapter is not configured; SET BUT UNPARSABLE is an `Err` the operator must see, because a typo would otherwise read as "no co-ops configured" and quietly drop a whole delivery channel.
    pub coopcycle_instances: Option<String>,
    /// HubRise API base-URL override (mock/staging). Unset, the adapter's own constant applies.
    pub hubrise_api_base_url: Option<String>,
    /// Public URL HubRise redirects back to after consent (this deployable's `/adapters/hubrise/oauth/callback`). Unset, the connect flow returns 503 rather than starting an OAuth round-trip it cannot finish. It must match the redirect registered on the HubRise app EXACTLY — a mismatch fails at HubRise's end, after the restaurant has already given consent.
    pub hubrise_connect_redirect_url: Option<String>,
    /// Scope requested on connect. Unset, the adapter asks for account-wide catalog + inventory read, so one token covers every location of the account. Narrowing it means a connected restaurant's catalog or stock silently stops syncing for the locations the scope no longer covers.
    pub hubrise_oauth_scope: Option<String>,
    /// TCP port the HTTP server binds. Render injects this; a mismatch means the platform health check never reaches the app and the deploy fails.
    pub port: i64,
    /// Directory served for the Leptos/WASM bundle. Wrong path, the storefront loads no assets.
    pub web_assets_dir: String,
    /// Short git SHA baked into the image at build time (ADR-20260721-175411) and reported by /health and the X-VERSION header. Unset, `build_version()` substitutes `dev-<crate version>` for local and uncontainerized runs, so a build that forgot it is identifiable AS unidentified. Deliberately declares NO `default`: the fallback is COMPUTED (it interpolates the crate version), and a spec default of plain `dev` would state a value the runtime never produces — a false declaration is worse than an absent one.
    pub captain_build_version: Option<String>,
}

impl Config {
    /// Resolve from the process environment, returning the config AND every missing required
    /// key. Both, always: the warn-only rollout phase (`CONFIG_ENFORCE=false`, D5) has to boot
    /// with the config it managed to build while still reporting what was absent. A missing
    /// required string resolves to empty — the caller decides whether that is fatal.
    pub fn resolve() -> (Self, ConfigProblems) {
        Self::resolve_inner()
    }

    /// Strict form: `Err` when anything required is missing. Used by tests and any caller that
    /// wants no warn-only escape hatch.
    pub fn from_env() -> Result<Self, MissingConfig> {
        let (cfg, problems) = Self::resolve_inner();
        if problems.is_empty() {
            Ok(cfg)
        } else {
            Err(MissingConfig { profile: cfg.profile, problems })
        }
    }

    /// Whether a configuration problem must STOP the app. Decided by the PROFILE, not by a
    /// separate toggle (product-owner directive 2026-07-29): production and staging stop,
    /// development reports and continues. Stopping is safe on Render — an exiting container
    /// fails the deploy and the PREVIOUS version keeps serving, so a misconfigured build can
    /// never replace a working one.
    pub fn must_stop_on_problems(&self) -> bool {
        !matches!(self.profile, Profile::Development)
    }

    fn resolve_inner() -> (Self, ConfigProblems) {
        let profile = match raw("APP_PROFILE").as_deref() {
            Some("production") => Profile::Production,
            Some("staging") => Profile::Staging,
            Some("development") | None => Profile::Development,
            Some(other) => {
                println!("APP_PROFILE: unrecognised value {other:?} -- using development.");
                Profile::Development
            }
        };
        let mut problems = ConfigProblems::default();
        let database_url = raw("DATABASE_URL");
        if database_url.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "DATABASE_URL", gates: "Postgres pool: the event store, every read model and every background worker. Unset, /health reports `not_configured` (503) and no worker is constructed at all." });
        }
        let database_url = database_url.unwrap_or_default();
        let supabase_url = raw("SUPABASE_URL").or_else(|| baked("SUPABASE_URL", profile).map(str::to_string));
        if supabase_url.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "SUPABASE_URL", gates: "Supabase Auth base URL for the passwordless OTP/magic-link flows. Unset, the identity service is the fail-closed stand-in and every login is refused." });
        }
        let supabase_url = supabase_url.unwrap_or_default();
        let supabase_publishable_key = raw("SUPABASE_PUBLISHABLE_KEY").or_else(|| baked("SUPABASE_PUBLISHABLE_KEY", profile).map(str::to_string));
        if supabase_publishable_key.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "SUPABASE_PUBLISHABLE_KEY", gates: "Supabase anon key sent as the `apikey` header on OTP flows. Unset, identity is fail-closed (auth stays anonymous-only)." });
        }
        let supabase_publishable_key = supabase_publishable_key.unwrap_or_default();
        let supabase_jwks_url = raw("SUPABASE_JWKS_URL").or_else(|| baked("SUPABASE_JWKS_URL", profile).map(str::to_string));
        if supabase_jwks_url.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "SUPABASE_JWKS_URL", gates: "JWKS endpoint used to verify Supabase-issued JWTs. Unset, tokens cannot be verified and every authenticated request falls back to anonymous." });
        }
        let supabase_jwks_url = supabase_jwks_url.unwrap_or_default();
        let auth_session_key = raw("AUTH_SESSION_KEY");
        if auth_session_key.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "AUTH_SESSION_KEY", gates: "AES-256-GCM key (32 bytes, 64 hex chars or base64) encrypting parked auth sessions at rest. Unset OR malformed, the store is the no-op: parking succeeds, claiming yields nothing, and login SILENTLY degrades to anonymous-only. Rotating it invalidates every in-flight login." });
        }
        let auth_session_key = auth_session_key.unwrap_or_default();
        let supabase_sms_hook_secret = raw("SUPABASE_SMS_HOOK_SECRET");
        let stripe_secret_key = raw("STRIPE_SECRET_KEY");
        if stripe_secret_key.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "STRIPE_SECRET_KEY", gates: "Stripe API key for PaymentIntents. Unset, the payment gateway is the fail-closed stand-in and no checkout can complete. The `sk_test_` / `sk_live_` prefix determines the MODE, which is reported (never the key) so \"is production actually live?\" is answerable." });
        }
        let stripe_secret_key = stripe_secret_key.unwrap_or_default();
        let stripe_webhook_secret = raw("STRIPE_WEBHOOK_SECRET");
        if stripe_webhook_secret.is_none() && matches!(profile, Profile::Staging | Profile::Production) {
            problems.missing.push(MissingKey { name: "STRIPE_WEBHOOK_SECRET", gates: "HMAC secret verifying `POST /adapters/stripe/webhooks` signatures. Unset, the endpoint fails closed (503) and PaymentCaptured NEVER REACHES THE DOMAIN — the customer is charged and the restaurant is never told. Stripe issues a DIFFERENT secret per mode: it must be switched together with STRIPE_SECRET_KEY." });
        }
        let stripe_webhook_secret = stripe_webhook_secret.unwrap_or_default();
        let honeycomb_api_key = raw("HONEYCOMB_API_KEY");
        let honeycomb_api_endpoint = raw("HONEYCOMB_API_ENDPOINT").or_else(|| baked("HONEYCOMB_API_ENDPOINT", profile).map(str::to_string));
        let honeycomb_api_endpoint = honeycomb_api_endpoint.unwrap_or_else(|| "https://api.eu1.honeycomb.io".to_string());
        let honeycomb_dataset = raw("HONEYCOMB_DATASET").or_else(|| baked("HONEYCOMB_DATASET", profile).map(str::to_string));
        let honeycomb_dataset = honeycomb_dataset.unwrap_or_else(|| "captain-food-dev".to_string());
        let otel_traces_sample_ratio = raw("OTEL_TRACES_SAMPLE_RATIO").or_else(|| baked("OTEL_TRACES_SAMPLE_RATIO", profile).map(str::to_string));
        let otel_traces_sample_ratio = otel_traces_sample_ratio.unwrap_or_else(|| "1.0".to_string());
        let log_level = raw("LOG_LEVEL").or_else(|| baked("LOG_LEVEL", profile).map(str::to_string));
        let log_level = log_level.unwrap_or_else(|| "info".to_string());
        let hubrise_client_id = raw("HUBRISE_CLIENT_ID");
        let hubrise_webhook_secret = raw("HUBRISE_WEBHOOK_SECRET");
        let external_api_tokens = raw("EXTERNAL_API_TOKENS");
        let internal_trigger_token = raw("INTERNAL_TRIGGER_TOKEN");
        let delivery_offer_max_ttl_seconds = raw("DELIVERY_OFFER_MAX_TTL_SECONDS").and_then(|v| v.parse::<i64>().ok()).unwrap_or(900);
        let run_projector = raw("RUN_PROJECTOR")
            .or_else(|| baked("RUN_PROJECTOR", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_PROJECTOR", &v, true))
            .unwrap_or(true);
        let run_process_managers = raw("RUN_PROCESS_MANAGERS")
            .or_else(|| baked("RUN_PROCESS_MANAGERS", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_PROCESS_MANAGERS", &v, true))
            .unwrap_or(true);
        let run_inbound_drain = raw("RUN_INBOUND_DRAIN")
            .or_else(|| baked("RUN_INBOUND_DRAIN", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_INBOUND_DRAIN", &v, true))
            .unwrap_or(true);
        let run_retention_sweep = raw("RUN_RETENTION_SWEEP")
            .or_else(|| baked("RUN_RETENTION_SWEEP", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_RETENTION_SWEEP", &v, true))
            .unwrap_or(true);
        let run_sirene_worker = raw("RUN_SIRENE_WORKER")
            .or_else(|| baked("RUN_SIRENE_WORKER", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_SIRENE_WORKER", &v, false))
            .unwrap_or(false);
        let run_delivery_offer_timeout = raw("RUN_DELIVERY_OFFER_TIMEOUT")
            .or_else(|| baked("RUN_DELIVERY_OFFER_TIMEOUT", profile).map(str::to_string))
            .map(|v| parse_bool("RUN_DELIVERY_OFFER_TIMEOUT", &v, true))
            .unwrap_or(true);
        let ovh_application_key = raw("OVH_APPLICATION_KEY");
        let ovh_application_secret = raw("OVH_APPLICATION_SECRET");
        let ovh_consumer_key = raw("OVH_CONSUMER_KEY");
        let ovh_sms_service_name = raw("OVH_SMS_SERVICE_NAME");
        let ovh_sms_sender = raw("OVH_SMS_SENDER");
        let ovh_endpoint = raw("OVH_ENDPOINT");
        let avelo37_api_key = raw("AVELO37_API_KEY");
        let avelo37_api_base_url = raw("AVELO37_API_BASE_URL");
        let avelo37_webhook_secret = raw("AVELO37_WEBHOOK_SECRET");
        let uber_direct_customer_id = raw("UBER_DIRECT_CUSTOMER_ID");
        let uber_direct_client_id = raw("UBER_DIRECT_CLIENT_ID");
        let uber_direct_client_secret = raw("UBER_DIRECT_CLIENT_SECRET");
        let uber_direct_webhook_secret = raw("UBER_DIRECT_WEBHOOK_SECRET");
        let uber_direct_base_url = raw("UBER_DIRECT_BASE_URL");
        let uber_direct_token_url = raw("UBER_DIRECT_TOKEN_URL");
        let uber_direct_scope = raw("UBER_DIRECT_SCOPE");
        let coopcycle_instances = raw("COOPCYCLE_INSTANCES");
        let hubrise_api_base_url = raw("HUBRISE_API_BASE_URL");
        let hubrise_connect_redirect_url = raw("HUBRISE_CONNECT_REDIRECT_URL");
        let hubrise_oauth_scope = raw("HUBRISE_OAUTH_SCOPE");
        let port = raw("PORT").and_then(|v| v.parse::<i64>().ok()).unwrap_or(8080);
        let web_assets_dir = raw("WEB_ASSETS_DIR");
        let web_assets_dir = web_assets_dir.unwrap_or_else(|| "/app/web-assets".to_string());
        let captain_build_version = raw("CAPTAIN_BUILD_VERSION");
        if let Some(v) = Some(database_url.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^postgres(ql)?://", v) {
                problems.invalid.push(InvalidKey { name: "DATABASE_URL", scalar: "PostgresUrl", pattern: r"^postgres(ql)?://", gates: "Postgres pool: the event store, every read model and every background worker. Unset, /health reports `not_configured` (503) and no worker is constructed at all." });
            }
        }
        if let Some(v) = Some(supabase_url.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "SUPABASE_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "Supabase Auth base URL for the passwordless OTP/magic-link flows. Unset, the identity service is the fail-closed stand-in and every login is refused." });
            }
        }
        if let Some(v) = Some(supabase_jwks_url.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "SUPABASE_JWKS_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "JWKS endpoint used to verify Supabase-issued JWTs. Unset, tokens cannot be verified and every authenticated request falls back to anonymous." });
            }
        }
        if let Some(v) = Some(auth_session_key.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^([0-9a-fA-F]{64}|[A-Za-z0-9+/]{43}=)$", v) {
                problems.invalid.push(InvalidKey { name: "AUTH_SESSION_KEY", scalar: "AuthSessionKey", pattern: r"^([0-9a-fA-F]{64}|[A-Za-z0-9+/]{43}=)$", gates: "AES-256-GCM key (32 bytes, 64 hex chars or base64) encrypting parked auth sessions at rest. Unset OR malformed, the store is the no-op: parking succeeds, claiming yields nothing, and login SILENTLY degrades to anonymous-only. Rotating it invalidates every in-flight login." });
            }
        }
        if let Some(v) = Some(stripe_secret_key.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^sk_(test|live)_[A-Za-z0-9]+$", v) {
                problems.invalid.push(InvalidKey { name: "STRIPE_SECRET_KEY", scalar: "StripeSecretKey", pattern: r"^sk_(test|live)_[A-Za-z0-9]+$", gates: "Stripe API key for PaymentIntents. Unset, the payment gateway is the fail-closed stand-in and no checkout can complete. The `sk_test_` / `sk_live_` prefix determines the MODE, which is reported (never the key) so \"is production actually live?\" is answerable." });
            }
        }
        if let Some(v) = Some(stripe_webhook_secret.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^whsec_[A-Za-z0-9_-]+$", v) {
                problems.invalid.push(InvalidKey { name: "STRIPE_WEBHOOK_SECRET", scalar: "StripeWebhookSecret", pattern: r"^whsec_[A-Za-z0-9_-]+$", gates: "HMAC secret verifying `POST /adapters/stripe/webhooks` signatures. Unset, the endpoint fails closed (503) and PaymentCaptured NEVER REACHES THE DOMAIN — the customer is charged and the restaurant is never told. Stripe issues a DIFFERENT secret per mode: it must be switched together with STRIPE_SECRET_KEY." });
            }
        }
        if let Some(v) = honeycomb_api_key.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^[A-Za-z0-9_]{20,120}$", v) {
                problems.invalid.push(InvalidKey { name: "HONEYCOMB_API_KEY", scalar: "HoneycombIngestKey", pattern: r"^[A-Za-z0-9_]{20,120}$", gates: "Honeycomb INGEST key for the OTLP trace/metric exporter (`x-honeycomb-team`). Unset, the exporter is not constructed at all and the app runs with local structured logs only — every span is built and dropped, so a production incident is diagnosed by reading stdout, which is the pre-#191 situation. This must be an INGEST key: a management key (`<id>:<secret>`, what the Honeycomb MCP server and Query API use) has a different shape and is rejected at startup rather than failing as an opaque 401 on the first export." });
            }
        }
        if let Some(v) = Some(honeycomb_api_endpoint.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "HONEYCOMB_API_ENDPOINT", scalar: "HttpsUrl", pattern: r"^https?://", gates: "OTLP/HTTP base endpoint. Defaults to and is baked as the **EU** host (`api.eu1.honeycomb.io`) — the US host `api.honeycomb.io` is a GDPR decision, not a preference, because spans carry customer and order ids (ADR-0042 pinned data to Frankfurt). Pointed at the wrong region, exports 401 against an account that does not hold the key and telemetry is silently absent." });
            }
        }
        if let Some(v) = Some(otel_traces_sample_ratio.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^(0(\\.[0-9]+)?|1(\\.0+)?)$", v) {
                problems.invalid.push(InvalidKey { name: "OTEL_TRACES_SAMPLE_RATIO", scalar: "TraceSampleRatio", pattern: r"^(0(\\.[0-9]+)?|1(\\.0+)?)$", gates: "Head-sampling probability, parent-respecting. Baked at `1.0` (keep everything) because PROP-170500 D2's reasoning holds at V0 volume: \"head-sampling would mostly discard the interesting traces\". This is the dial to turn DOWN if ingest cost becomes real — turning it down before there is volume buys nothing and loses the traces that explain the incidents. Set to 0 and traces stop; the metrics and logs continue, so the app looks healthy while being undiagnosable." });
            }
        }
        if let Some(v) = Some(log_level.as_str()) {
            if !v.is_empty() && !matches_pattern(r"^(?i)(trace|debug|info|warn|error)$", v) {
                problems.invalid.push(InvalidKey { name: "LOG_LEVEL", scalar: "LogLevel", pattern: r"^(?i)(trace|debug|info|warn|error)$", gates: "Minimum severity for the structured JSON log layer. At `error` the boot report and every worker lifecycle line disappear, which is how a paused pipeline becomes invisible (issue #220) — so the baked value stays `info` and `debug` is an incident tool, not a default." });
            }
        }
        if let Some(v) = avelo37_api_base_url.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "AVELO37_API_BASE_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "Base-URL override pointing the client at a staging or mock Avelo37. Unset, the client uses its own production constant -- hence no `default` here, which would duplicate it." });
            }
        }
        if let Some(v) = uber_direct_base_url.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "UBER_DIRECT_BASE_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "API base-URL override (tests point this at a local mock). Unset, the adapter's own production constant applies -- no `default` here for the same reason." });
            }
        }
        if let Some(v) = uber_direct_token_url.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "UBER_DIRECT_TOKEN_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "OAuth2 token-endpoint override. Unset, the adapter's own constant applies." });
            }
        }
        if let Some(v) = hubrise_api_base_url.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "HUBRISE_API_BASE_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "HubRise API base-URL override (mock/staging). Unset, the adapter's own constant applies." });
            }
        }
        if let Some(v) = hubrise_connect_redirect_url.as_deref() {
            if !v.is_empty() && !matches_pattern(r"^https?://", v) {
                problems.invalid.push(InvalidKey { name: "HUBRISE_CONNECT_REDIRECT_URL", scalar: "HttpsUrl", pattern: r"^https?://", gates: "Public URL HubRise redirects back to after consent (this deployable's `/adapters/hubrise/oauth/callback`). Unset, the connect flow returns 503 rather than starting an OAuth round-trip it cannot finish. It must match the redirect registered on the HubRise app EXACTLY — a mismatch fails at HubRise's end, after the restaurant has already given consent." });
            }
        }
        (
            Self {
                profile,
                database_url,
                supabase_url,
                supabase_publishable_key,
                supabase_jwks_url,
                auth_session_key,
                supabase_sms_hook_secret,
                stripe_secret_key,
                stripe_webhook_secret,
                honeycomb_api_key,
                honeycomb_api_endpoint,
                honeycomb_dataset,
                otel_traces_sample_ratio,
                log_level,
                hubrise_client_id,
                hubrise_webhook_secret,
                external_api_tokens,
                internal_trigger_token,
                delivery_offer_max_ttl_seconds,
                run_projector,
                run_process_managers,
                run_inbound_drain,
                run_retention_sweep,
                run_sirene_worker,
                run_delivery_offer_timeout,
                ovh_application_key,
                ovh_application_secret,
                ovh_consumer_key,
                ovh_sms_service_name,
                ovh_sms_sender,
                ovh_endpoint,
                avelo37_api_key,
                avelo37_api_base_url,
                avelo37_webhook_secret,
                uber_direct_customer_id,
                uber_direct_client_id,
                uber_direct_client_secret,
                uber_direct_webhook_secret,
                uber_direct_base_url,
                uber_direct_token_url,
                uber_direct_scope,
                coopcycle_instances,
                hubrise_api_base_url,
                hubrise_connect_redirect_url,
                hubrise_oauth_scope,
                port,
                web_assets_dir,
                captain_build_version,
            },
            problems,
        )
    }

    /// What actually resolved, for the boot log. Secrets render as `set` / `unset`, never as a
    /// value; a key declaring `mode_of: stripe` additionally reports its derived mode, so
    /// "is production actually live?" is answerable without reading a secret.
    pub fn boot_report(&self) -> String {
        let mut out = format!("config: profile={}, {} keys resolved\n", self.profile, KEY_COUNT);
        out.push_str(&format!("  DATABASE_URL               = {}\n", if self.database_url.is_empty() { "unset" } else { "set" }));
        out.push_str(&format!("  SUPABASE_URL               = {}\n", self.supabase_url));
        out.push_str(&format!("  SUPABASE_PUBLISHABLE_KEY   = {}\n", self.supabase_publishable_key));
        out.push_str(&format!("  SUPABASE_JWKS_URL          = {}\n", self.supabase_jwks_url));
        out.push_str(&format!("  AUTH_SESSION_KEY           = {}\n", if self.auth_session_key.is_empty() { "unset" } else { "set" }));
        out.push_str(&format!("  SUPABASE_SMS_HOOK_SECRET   = {}\n", if self.supabase_sms_hook_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  STRIPE_SECRET_KEY          = {}\n", if self.stripe_secret_key.is_empty() { "unset".to_string() } else { format!("set [{} mode]", stripe_mode(&self.stripe_secret_key)) }));
        out.push_str(&format!("  STRIPE_WEBHOOK_SECRET      = {}\n", if self.stripe_webhook_secret.is_empty() { "unset" } else { "set" }));
        out.push_str(&format!("  HONEYCOMB_API_KEY          = {}\n", if self.honeycomb_api_key.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  HONEYCOMB_API_ENDPOINT     = {}\n", self.honeycomb_api_endpoint));
        out.push_str(&format!("  HONEYCOMB_DATASET          = {}\n", self.honeycomb_dataset));
        out.push_str(&format!("  OTEL_TRACES_SAMPLE_RATIO   = {}\n", self.otel_traces_sample_ratio));
        out.push_str(&format!("  LOG_LEVEL                  = {}\n", self.log_level));
        out.push_str(&format!("  HUBRISE_CLIENT_ID          = {}\n", self.hubrise_client_id.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  HUBRISE_WEBHOOK_SECRET     = {}\n", if self.hubrise_webhook_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  EXTERNAL_API_TOKENS        = {}\n", if self.external_api_tokens.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  INTERNAL_TRIGGER_TOKEN     = {}\n", if self.internal_trigger_token.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  DELIVERY_OFFER_MAX_TTL_SECONDS = {}\n", self.delivery_offer_max_ttl_seconds));
        out.push_str(&format!("  RUN_PROJECTOR              = {}\n", self.run_projector));
        out.push_str(&format!("  RUN_PROCESS_MANAGERS       = {}\n", self.run_process_managers));
        out.push_str(&format!("  RUN_INBOUND_DRAIN          = {}\n", self.run_inbound_drain));
        out.push_str(&format!("  RUN_RETENTION_SWEEP        = {}\n", self.run_retention_sweep));
        out.push_str(&format!("  RUN_SIRENE_WORKER          = {}\n", self.run_sirene_worker));
        out.push_str(&format!("  RUN_DELIVERY_OFFER_TIMEOUT = {}\n", self.run_delivery_offer_timeout));
        out.push_str(&format!("  OVH_APPLICATION_KEY        = {}\n", if self.ovh_application_key.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  OVH_APPLICATION_SECRET     = {}\n", if self.ovh_application_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  OVH_CONSUMER_KEY           = {}\n", if self.ovh_consumer_key.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  OVH_SMS_SERVICE_NAME       = {}\n", if self.ovh_sms_service_name.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  OVH_SMS_SENDER             = {}\n", self.ovh_sms_sender.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  OVH_ENDPOINT               = {}\n", self.ovh_endpoint.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  AVELO37_API_KEY            = {}\n", if self.avelo37_api_key.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  AVELO37_API_BASE_URL       = {}\n", self.avelo37_api_base_url.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  AVELO37_WEBHOOK_SECRET     = {}\n", if self.avelo37_webhook_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  UBER_DIRECT_CUSTOMER_ID    = {}\n", if self.uber_direct_customer_id.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  UBER_DIRECT_CLIENT_ID      = {}\n", if self.uber_direct_client_id.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  UBER_DIRECT_CLIENT_SECRET  = {}\n", if self.uber_direct_client_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  UBER_DIRECT_WEBHOOK_SECRET = {}\n", if self.uber_direct_webhook_secret.is_some() { "set" } else { "unset" }));
        out.push_str(&format!("  UBER_DIRECT_BASE_URL       = {}\n", self.uber_direct_base_url.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  UBER_DIRECT_TOKEN_URL      = {}\n", self.uber_direct_token_url.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  UBER_DIRECT_SCOPE          = {}\n", self.uber_direct_scope.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  COOPCYCLE_INSTANCES        = {}\n", self.coopcycle_instances.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  HUBRISE_API_BASE_URL       = {}\n", self.hubrise_api_base_url.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  HUBRISE_CONNECT_REDIRECT_URL = {}\n", self.hubrise_connect_redirect_url.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  HUBRISE_OAUTH_SCOPE        = {}\n", self.hubrise_oauth_scope.as_deref().unwrap_or("unset")));
        out.push_str(&format!("  PORT                       = {}\n", self.port));
        out.push_str(&format!("  WEB_ASSETS_DIR             = {}\n", self.web_assets_dir));
        out.push_str(&format!("  CAPTAIN_BUILD_VERSION      = {}\n", self.captain_build_version.as_deref().unwrap_or("unset")));
        out
    }
}

